-- Inventario de repuestos: el catálogo del taller, cuántos hay en cada sucursal y cada
-- movimiento (compra, salida en una orden, ajuste por conteo). Solo agrega tablas y una
-- columna vacía: no cambia ni borra datos. Las FK son DEFERRABLE como las del resto
-- del esquema: el respaldo las necesita así para restaurar (scripts/verificar-restauracion.sql).

CREATE TABLE IF NOT EXISTS "repuestos" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "codigo" varchar(60),
  "nombre" varchar(200) NOT NULL,
  "marca" varchar(100),
  "unidad" varchar(20) NOT NULL DEFAULT 'unidad',
  -- Lo que le cuesta al taller y lo que cobra. El precio es el que se propone al
  -- agregarlo a una orden; ahí se puede cambiar.
  "costo" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("costo" >= 0),
  "precio" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("precio" >= 0),
  -- Por debajo de este número aparece como "por agotarse".
  "minimo" integer NOT NULL DEFAULT 0 CHECK ("minimo" >= 0),
  "activo" smallint NOT NULL DEFAULT 1 CHECK ("activo" IN (0, 1)),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_repuestos_tenant" ON "repuestos" ("tenant_id", "activo", "nombre");
-- El código, si lo tiene, no se repite dentro del taller (sin distinguir mayúsculas).
CREATE UNIQUE INDEX IF NOT EXISTS "uq_repuestos_tenant_codigo" ON "repuestos" ("tenant_id", LOWER("codigo")) WHERE "codigo" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "repuesto_existencias" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "repuesto_id" integer NOT NULL REFERENCES "repuestos" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "sucursal_id" integer NOT NULL REFERENCES "sucursales" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  -- Puede quedar negativa: un taller entrega antes de anotar la compra, y bloquear la
  -- entrega por eso sería peor. La pantalla lo muestra en rojo.
  "cantidad" integer NOT NULL DEFAULT 0,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_existencia" UNIQUE ("tenant_id", "repuesto_id", "sucursal_id")
);

CREATE TABLE IF NOT EXISTS "movimientos_inventario" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "tenant_id" integer NOT NULL REFERENCES "tenants" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "repuesto_id" integer NOT NULL REFERENCES "repuestos" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "sucursal_id" integer NOT NULL REFERENCES "sucursales" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "tipo" varchar(12) NOT NULL CHECK ("tipo" IN ('entrada', 'salida', 'ajuste')),
  -- Con signo: + entra, - sale.
  "cantidad" integer NOT NULL CHECK ("cantidad" <> 0),
  "existencia_despues" integer NOT NULL,
  "costo_unitario" numeric(12,2),
  "orden_id" integer REFERENCES "ordenes_trabajo" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "orden_repuesto_id" integer,
  "proveedor" varchar(150),
  "documento" varchar(60),
  "nota" varchar(300),
  "usuario_id" integer REFERENCES "usuarios" ("id") DEFERRABLE INITIALLY IMMEDIATE,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_movimientos_repuesto" ON "movimientos_inventario" ("tenant_id", "repuesto_id", "id");
-- Una pieza de una orden descuenta una sola vez, aunque la entrega se reintente.
CREATE UNIQUE INDEX IF NOT EXISTS "uq_movimiento_salida_pieza" ON "movimientos_inventario" ("tenant_id", "orden_repuesto_id") WHERE "tipo" = 'salida';

-- Las piezas de una orden pueden venir del catálogo. Vacío = escrita a mano (como hasta hoy).
ALTER TABLE "orden_repuestos" ADD COLUMN IF NOT EXISTS "repuesto_id" integer REFERENCES "repuestos" ("id") DEFERRABLE INITIALLY IMMEDIATE;
